import React, { useState } from 'react';
import styled from 'styled-components';
import Picker from 'emoji-picker-react';

export default function ChatInput({ handleSendMsg }) {
  const [showEmojiPicker, setShowEmojiPicker] = useState(false);
  const [msg, setMsg] = useState('');

  const handleEmojiPickerHandler = () => {
    setShowEmojiPicker(!showEmojiPicker);
  };
  const handleEmojiClick = (event, emoji) => {
    let message = msg;
    message += emoji.emoji;
    setMsg(message);
  };
  const sendChat = (event) => {
    const a = document.querySelector('.input__div').textContent;
    console.log(a);
    console.log(event.target);
    event.preventDefault();
    if (msg.length > 0) {
      handleSendMsg(msg);
      setMsg('');
    }
  };

  return (
    <Container>
      {/* <div className="button_container"> */}
      <div className="emoji">
        <ion-icon
          name="happy-outline"
          onClick={handleEmojiPickerHandler}
        ></ion-icon>
        {/* <span className="icon">emoji-icon</span> */}
        {showEmojiPicker && <Picker onEmojiClick={handleEmojiClick} />}
      </div>
      <ion-icon name="attach-outline"></ion-icon>
      {/* </div> */}
      <form
        className="input_container"
        onChange={(e) => sendChat(e)}
        onSubmit={(e) => sendChat(e)}
      >
        <div className="input">
          <div
            title="Type your message"
            className="input__div"
            role="textbox"
            contentEditable="true"
            onKeyDown={(e) => console.log(e.target.textContent)}
          ></div>
        </div>
        {/* <input type="text" /> */}
        <button className="submit">
          <ion-icon name="paper-plane-outline"></ion-icon>
        </button>
      </form>
    </Container>
  );
}

const Container = styled.div`
  background: #1b0029;
  display: flex;
  /* justify-content: space-between; */
  align-items: flex-end;
  padding: 15px;

  ion-icon {
    font-size: 1.8rem;
    color: hsl(208 22% 73% / 0.49);
    font-weight: 700;
    cursor: pointer;
    margin-bottom: 10px;
  }
  ion-icon:nth-child(1) {
    margin-right: 15px;
  }
  ion-icon:nth-child(2) {
    transform: rotate(-20deg);
  }
  .input_container {
    display: flex;
    width: 100%;
  }
  .input {
    flex: 1;
    width: 90%;
    border-radius: 8px;
    margin: 5px 10px;
    overflow: hidden;
    padding: 9px 12px 11px;
    background: hsl(279 100% 12%);
    color: hsl(208 22% 83%);
    word-break: break-all;
    word-wrap: break-word;
    overflow-wrap: break-word;
    height: auto;
  }

  .input__div {
    outline: none;
    border: none;
    height: 100%;
    width: 100%;
    max-height: 100px;
    overflow-y: auto;
    flex: 1;
  }

  .input__div::-webkit-scrollbar-thumb {
    border-radius: 0;
  }
`;
